    export interface Agent {
        readonly id: SessionId;
        readonly options: AgentOptions;
        readonly session: Session;
        readonly status: AgentStatus;
        readonly ctx: Context;
        send(content: ContentBlock[], options?: SendOptions): void;
        steer(content: ContentBlock[], options?: SendOptions): void;
        inject(content: ContentBlock[], options?: InjectOptions): void;
        cancel(cause?: AgentCancelCause): void;
        whenIdle(): Promise<void>;
    }
    export type AgentCancelCause = {
        readonly kind: 'user';
    } | {
        readonly kind: 'parent';
    };
    export interface AgentOptions {
        provider?: string;
        model?: string;
    }
    export type AgentStatus = 'idle' | 'running' | 'disposed';
    export type Branded<B extends string> = string & {
        readonly [BRAND]: B;
    };
    export type CallId = Branded<'CallId'>;
    export interface DiffCallView {
        card: 'diff';
        title: string;
        diffs: FileDiff[];
        locations?: FileLocation[];
    }
    export interface DiffResultView {
        card: 'diff';
        title?: string;
        diffs: FileDiff[];
    }
    export interface FileDiff {
        path: string;
        oldText: string | null;
        newText: string;
    }
    export interface FileLocation {
        path: string;
        line?: number;
    }
    export interface GenericCallView {
        card: 'generic';
        title: string;
        kind?: ToolCallKind;
        rawInput?: unknown;
        content?: ContentBlock[];
        locations?: FileLocation[];
    }
    export interface GenericResultView {
        card: 'generic';
        title?: string;
        content?: ContentBlock[];
    }
    export interface HookContext {
        content: ContentBlock[];
        source: MessageSource;
        placement?: 'separate' | 'prompt-prefix';
        meta?: JsonValue;
    }
    export interface InjectOptions extends Omit<SendOptions, 'contexts'> {
        meta?: JsonValue;
    }
    export type JsonValue = null | boolean | number | string | JsonValue[] | {
        [key: string]: JsonValue;
    };
    export type MessageSource = MessageSourceMap[keyof MessageSourceMap];
    export interface MessageSourceMap {
        user: {
            kind: 'user';
        };
        plugin: {
            kind: 'plugin';
            plugin: string;
        };
    }
    export type ScopeKey = object;
    export interface SendOptions {
        source?: MessageSource;
        contexts?: HookContext[];
    }
    export type SessionId = Branded<'SessionId'>;
    export interface TerminalCallView {
        card: 'terminal';
        title: string;
        description?: string;
        cwd?: string;
    }
    export interface TerminalResultView {
        card: 'terminal';
        title?: string;
        output?: string;
        exitCode?: number;
        signal?: string;
    }
    export type ToolCallKind = 'read' | 'edit' | 'delete' | 'move' | 'search' | 'execute' | 'fetch' | 'other';
    export type ToolCallView = GenericCallView | TerminalCallView | DiffCallView;
    export interface ToolDefinition extends ToolSchema {
        execute(args: unknown, exec: ToolRunContext): Promise<ToolExecuteReturn>;
        timeoutMs?: number;
        isConcurrencySafe?(args: unknown): boolean;
        presentCall?(args: unknown): ToolCallView | undefined;
        presentResult?(args: unknown, result: ToolResult): ToolResultView | undefined;
    }
    export interface ToolErrorInfo {
        name: string;
        code: string;
    }
    export type ToolExecuteReturn = ContentBlock[] | {
        content: ContentBlock[];
        meta?: unknown;
    };
    export interface ToolExecution extends ToolExecutionInput {
        readonly token: ToolExecutionToken;
    }
    export interface ToolExecutionInput {
        readonly callId: CallId;
        readonly name: string;
        readonly arguments: unknown;
        readonly agent?: Agent;
        readonly parent?: ToolExecutionToken;
        readonly signal: AbortSignal;
    }
    export type ToolExecutionMode = {
        kind: 'parallel';
    } | {
        kind: 'exclusive';
    };
    export interface ToolExecutionResult {
        content: ContentBlock[];
        isError: boolean;
        error?: ToolErrorInfo;
        additionalContexts?: HookContext[];
        meta?: unknown;
    }
    export type ToolExecutionToken = symbol & {
        readonly [toolExecutionTokenBrand]: true;
    };
    export type ToolGuard = (execution: Readonly<ToolExecution>) => string | undefined;
    export interface ToolRestriction {
        readonly allow?: readonly string[];
        readonly deny?: readonly string[];
    }
    export interface ToolResult {
        content: ContentBlock[];
        isError: boolean;
        meta?: unknown;
    }
    export type ToolResultView = GenericResultView | TerminalResultView | DiffResultView;
    export interface ToolRunContext extends ToolExecution {
        deferContext(context: HookContext): void;
    }
    export interface ToolSchema {
        name: string;
        description: string;
        parameters: Record<string, unknown>;
    }
